import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"教育保障法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/43-教育保障法.md","filePath":"zh/43-教育保障法.md"}'),e={name:"zh/43-教育保障法.md"};function i(o,t,h,n,s,u){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="教育保障法" tabindex="-1">教育保障法 <a class="header-anchor" href="#教育保障法" aria-label="Permalink to &quot;教育保障法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>43</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>教育权、共生教育、修炼传承、终身学习、教育公平</td></tr></tbody></table><h2 id="一、立法目的与基本原则" tabindex="-1">一、立法目的与基本原则 <a class="header-anchor" href="#一、立法目的与基本原则" aria-label="Permalink to &quot;一、立法目的与基本原则&quot;">​</a></h2><p>《教育保障法》是锚点共生文明五部配套法之一，旨在保障衡元宙内一切生命的受教育权，建立以&quot;共生进化&quot;为核心理念的教育体系，为万族共进提供知识与人才支撑。</p><p>本法确立以下基本原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>教育公平原则</td><td>一切生命不分种族、修为、出身，均享有平等的受教育机会</td></tr><tr><td>因材施教原则</td><td>尊重每个生命的天赋差异与进化路径选择，提供个性化教育方案</td></tr><tr><td>知行合一原则</td><td>理论知识与实践修炼相结合，反对脱离实际的空谈教育</td></tr><tr><td>开放共享原则</td><td>教育资源向全社会开放，三百套本源修炼体系的基础法门免费传授</td></tr><tr><td>终身学习原则</td><td>教育贯穿生命全过程，支持各阶段的持续学习与能力提升</td></tr><tr><td>文化多元原则</td><td>尊重各族文化传统，鼓励多元文化交流与互鉴</td></tr></tbody></table><h2 id="二、受教育权的法律保障" tabindex="-1">二、受教育权的法律保障 <a class="header-anchor" href="#二、受教育权的法律保障" aria-label="Permalink to &quot;二、受教育权的法律保障&quot;">​</a></h2><p>本法明确规定，受教育权是共生宪法赋予每个生命的基本权利，国家与文明有义务保障这一权利的实现：</p><ol><li><strong>免费基础教育</strong>：所有生命均有权接受免费的基础教育，包括通用知识、基础修炼法门、共生文明理念等内容，学制为六至十二年，根据种族发育周期调整。</li><li><strong>免费修炼入门</strong>：三百套宇宙本源修炼体系的基础法门向所有生命免费开放，任何组织和个人不得将基础修炼法门据为私有并收费传授。</li><li><strong>升学机会平等</strong>：各级各类教育机构在招生中不得设置种族、修为、出身等歧视性条件，录取标准公开透明。</li><li><strong>特殊教育保障</strong>：为残疾生命、异族生命、偏远位面生命等群体提供适配的特殊教育资源与远程教育支持。</li><li><strong>教育救助制度</strong>：对经济困难的学习者提供助学金、奖学金与无息贷款，确保不因经济原因丧失受教育机会。</li></ol><h2 id="三、教育体系架构" tabindex="-1">三、教育体系架构 <a class="header-anchor" href="#三、教育体系架构" aria-label="Permalink to &quot;三、教育体系架构&quot;">​</a></h2><p>锚点共生文明的教育体系分为四个层级，各层级之间有机衔接：</p><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>目标</th><th>学制</th></tr></thead><tbody><tr><td>第一层级</td><td>启蒙教育</td><td>培养基本认知能力与共生意识，传授基础修炼法门</td><td>3-6年</td></tr><tr><td>第二层级</td><td>基础教育</td><td>系统学习通用知识与修炼理论，发现个体天赋方向</td><td>6-9年</td></tr><tr><td>第三层级</td><td>专业教育</td><td>针对选定的修炼体系或专业领域进行深入学习与实践</td><td>3-10年</td></tr><tr><td>第四层级</td><td>高阶研修</td><td>面向高阶修炼者与研究者的前沿探索与创新研修</td><td>不限</td></tr></tbody></table><p>此外，设立&quot;导师网络制度&quot;：达到一定修为的修炼者有义务在能力范围内指导初级修炼者，指导贡献计入联产承包机制的贡献量，享受相应的资源分配。</p><h2 id="四、教育机构与教师" tabindex="-1">四、教育机构与教师 <a class="header-anchor" href="#四、教育机构与教师" aria-label="Permalink to &quot;四、教育机构与教师&quot;">​</a></h2><ul><li><strong>公立教育机构</strong>：由国家或文明共同体设立，承担免费基础教育与公共教育服务，经费由公共积累保障。</li><li><strong>私立教育机构</strong>：由社会力量依法设立，可收取合理费用，但必须接受教育主管部门的监管，不得进行虚假宣传与掠夺式收费。</li><li><strong>修炼宗门</strong>：传统修炼组织经登记后可作为专业教育机构开展活动，必须遵守教育法规定，不得封闭垄断修炼资源。</li><li><strong>教师权利与义务</strong>：教师享有学术自由、合理报酬、职业培训等权利，同时负有教书育人、为人师表、保守学生隐私等义务。</li></ul><h2 id="五、教育内容与课程标准" tabindex="-1">五、教育内容与课程标准 <a class="header-anchor" href="#五、教育内容与课程标准" aria-label="Permalink to &quot;五、教育内容与课程标准&quot;">​</a></h2><p>教育内容必须符合以下要求：</p><ol><li>包含共生文明核心理念与反掠夺主义教育，培养学习者的共生意识。</li><li>包含三百套本源修炼体系的基础理论与入门法门。</li><li>包含宇宙法则、位面知识、生命科学等通用科学知识。</li><li>包含万族历史与文化，促进各族相互理解与尊重。</li><li>包含实践修炼与社会服务环节，培养知行合一的能力。</li><li>禁止传播掠夺式修炼理念与歧视性思想。</li></ol><h2 id="六、法律责任" tabindex="-1">六、法律责任 <a class="header-anchor" href="#六、法律责任" aria-label="Permalink to &quot;六、法律责任&quot;">​</a></h2><p>违反本法规定的行为，视情节轻重承担以下责任：</p><ul><li>拒绝或阻碍适龄生命接受义务教育的，责令改正并予以处罚。</li><li>教育机构违规收费、虚假宣传的，责令退还费用并处罚款，情节严重的吊销办学许可。</li><li>教师体罚或歧视学生的，给予处分，情节严重的撤销教师资格并追究法律责任。</li><li>将公共修炼资源据为私有、垄断收费的，没收违法所得并处罚款。</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《教育保障法》是锚点共生文明&quot;人人有路&quot;理念的教育实践。它通过保障受教育权、构建分层教育体系、开放修炼资源，确保每个生命都能获得适合自身的进化路径，为万族共进源源不断地输送知识与人才。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>40-共生宪法总纲</li><li>37-共生教育体系</li><li>10-三百套本源修炼体系总览</li><li>08-人人有路保障体系</li></ul>',25)])])}const _=a(e,[["render",i]]);export{c as __pageData,_ as default};
